window.OSCE_STRATEGY = [{"id": "newrx", "label": "New Prescription Counselling", "framework": "SAILS", "steps": ["Introduce yourself, confirm patient identity (name + DOB), and check privacy/consent to counsel.", "Store what they already know — ask what the prescriber told them about the diagnosis and medication (avoid repeating what they already understand).", "Action — explain in plain language what the drug does and why it was prescribed for them specifically.", "Instructions — how to take it (dose, timing, food/interactions), and what to do if a dose is missed.", "Life effects — expected side effects, how to manage minor ones, and what's serious enough to report.", "Seek help — red flags, when to call the pharmacy vs. seek urgent care, and confirm follow-up (labs, refill timing)."], "pitfalls": ["Reciting a monograph instead of tailoring to what the patient already knows", "Missing the ONE interaction or monitoring point that's the actual point of the station (e.g., levothyroxine + calcium, metformin + contrast dye)", "Forgetting to check understanding (teach-back) before closing"]}, {"id": "otc", "label": "OTC / Self-Care Triage", "framework": "WWHAM / ASMETHOD", "steps": ["Clarify who the product is for and confirm you're speaking with (or about) the right person.", "Who — age, pregnancy/breastfeeding status if relevant. What — symptoms, onset, duration, character. Action taken already. Medication history (Rx, OTC, herbals) and allergies.", "Actively screen for red flags/exclusions for self-treatment before recommending anything (duration too long, red-flag symptom, high-risk population, interacting current therapy).", "If self-care is appropriate: recommend a specific product/class, dose, and duration, with a clear stop-and-see-a-doctor point.", "If NOT appropriate for self-care: explain why in plain language and refer, without simply refusing."], "pitfalls": ["Jumping straight to a product recommendation before finishing the assessment", "Missing a red flag buried in the stem (e.g., cough duration, chest pain, unexplained weight loss)", "Recommending a product that interacts with a medication mentioned earlier in the stem"]}, {"id": "adr", "label": "Adverse Drug Reaction Report", "framework": "Assess → Severity → Act → Follow-up", "steps": ["Introduce yourself and gather the details: onset, timeline relative to the suspected drug, severity, and associated symptoms.", "Actively rule in/out the serious version of the reaction (e.g., dark urine + myopathy = possible rhabdomyolysis; not just 'sore muscles').", "Decide and state urgency clearly — stop the drug now vs. continue and monitor vs. this is expected/benign and self-limiting.", "Explain next steps: what testing is needed, whether to go to urgent care/ER today, and what alternative therapy might follow.", "Document and communicate with the prescriber; close the loop with the patient on what happens next."], "pitfalls": ["Reassuring the patient before confirming the reaction isn't dangerous", "Failing to explicitly say 'stop the drug' when that's the correct action", "Not identifying the single red-flag detail the case is testing (a lab value, a symptom pairing)"]}, {"id": "adherence", "label": "Non-Adherence / Motivational Interviewing", "framework": "Explore → Acknowledge → Inform → Collaborate → Follow-up (OARS)", "steps": ["Build rapport; open with an open-ended, non-judgmental question about how things have been going with the medication.", "Explore their reasons/beliefs/barriers without arguing or lecturing — use reflective listening.", "Acknowledge their perspective as valid before providing information (avoid 'yes, but...').", "Inform: give the missing clinical information (the risk they're underestimating) briefly and only once rapport is established.", "Collaborate on a concrete next step that respects their autonomy (dose change, reminder tool, follow-up visit) — don't issue ultimatums."], "pitfalls": ["Lecturing or scolding, which shuts down disclosure", "Assuming the barrier is knowledge when it's often cost, side effects, or beliefs", "Ending without one specific, agreed-upon next action"]}, {"id": "prescribercall", "label": "Prescriber Call", "framework": "SBAR", "steps": ["Introduce yourself and your pharmacy clearly, and state the reason for the call up front.", "Situation — the immediate issue in one sentence.", "Background — relevant patient history, labs, current therapy.", "Assessment — your clinical concern, stated specifically (not vague 'just checking').", "Recommendation — a concrete proposed action or alternative, not just a flagged problem.", "Confirm the plan, who follows up with the patient, and document the call."], "pitfalls": ["Presenting the problem without a recommendation", "Being vague about the actual clinical concern (say the number/threshold, not just 'the labs look off')", "Sounding confrontational instead of collaborative"]}, {"id": "refusal", "label": "Refusal / Regulatory Conflict", "framework": "Empathize → Explain → Explore safety → Offer alternative", "steps": ["Listen fully and respond with empathy before explaining any policy or legal constraint.", "Clearly explain the regulatory/professional reason you cannot do what's being asked, in plain non-accusatory language.", "Sensitively screen for safety concerns (withdrawal, diversion, pain crisis) without being accusatory.", "Offer a concrete alternative path forward (contacting the prescriber, an interim plan, a same-day appointment).", "Document the interaction thoroughly and close respectfully."], "pitfalls": ["Leading with a flat 'no' before any empathy or explanation", "Being accusatory toward a patient who may have a legitimate reason", "Failing to offer any alternative or next step"]}, {"id": "immunization", "label": "Immunization Screening & Counselling", "framework": "Screen → Consent → Administer counsel → Aftercare", "steps": ["Confirm identity, indication, and eligibility (age, interval since last dose, catch-up schedule if relevant).", "Screen contraindications/precautions: anaphylaxis to a prior dose or vaccine component, current acute illness, immunosuppression, pregnancy status if relevant to that vaccine.", "Obtain informed consent — explain the vaccine, common local/systemic reactions, and rare serious reactions in balanced, non-alarming language.", "Discuss same-day co-administration rules and timing with other vaccines/medications if relevant.", "Aftercare: observation period (typically 15 minutes), how to manage soreness/fever, and when to seek care (anaphylaxis signs)."], "pitfalls": ["Missing a contraindication buried in the patient's stated allergy history", "Forgetting the post-injection observation period", "Not documenting/reporting per the provincial immunization program"]}, {"id": "calculation", "label": "In-Station Calculation", "framework": "Extract → Set up → Solve → Sanity-check → State", "steps": ["Extract only the numbers/units you actually need from the stem; ignore distractor data.", "Set up the equation explicitly (write out units) before calculating — this is what earns partial marks and catches unit errors.", "Solve carefully, watching for unit conversions (mg vs. mcg, mL vs. L, mmol vs. mg).", "Sanity-check: does the final number make clinical/physical sense (e.g., a pediatric dose shouldn't exceed the adult max)?", "State the final answer clearly with correct units, and briefly explain your reasoning to the examiner."], "pitfalls": ["Skipping unit conversions (a classic trap: mcg/kg vs mg/kg, %w/v vs %w/w)", "Not showing work, so a small arithmetic slip loses all marks instead of partial credit", "Failing to sanity-check an answer that's clinically implausible"]}, {"id": "error", "label": "Medication Error Disclosure", "framework": "Acknowledge → Apologize → Assess harm → Act → Prevent", "steps": ["Acknowledge the error directly and honestly as soon as it is identified — do not minimize or deflect.", "Apologize sincerely without excessive self-blame or panic that alarms the patient unnecessarily.", "Assess actual/potential harm from the specific error (wrong drug, wrong dose, wrong patient) and give clear clinical guidance on what to do now.", "Act: correct the error, notify the prescriber if needed, and document per the pharmacy's incident-reporting process.", "Prevent: briefly note what will change to reduce recurrence (double-check process, systems fix) without being defensive."], "pitfalls": ["Being defensive or blaming a colleague/system in front of the patient", "Failing to give a clear clinical instruction (what to actually do about the error) alongside the apology", "Forgetting to mention documentation/incident reporting"]}, {"id": "assessment", "label": "Patient Assessment / History-Taking", "framework": "OPQRST + PMH/SH + red-flag screen", "steps": ["Onset, Provocation/Palliation, Quality, Region/Radiation, Severity, Timing of the presenting complaint.", "Past medical history, current medications (Rx/OTC/herbal), allergies, and relevant social history (travel, occupation, lifestyle).", "Actively screen for red flags specific to the presentation before considering self-care or minor-ailment prescribing.", "State a working assessment and plan, including whether this is within your scope to manage or needs referral.", "Explain the plan and safety-net advice to the patient in plain language."], "pitfalls": ["Skipping red-flag screening because the case initially sounds routine", "Not asking about travel history when relevant to infectious/tropical presentations", "Failing to state a clear plan at the end, even after gathering good history"]}, {"id": "difficult", "label": "Difficult Conversation", "framework": "Listen → Validate → Provide facts → Support → Plan", "steps": ["Let the person speak fully before responding; resist the urge to jump straight to facts or solutions.", "Validate the emotion in the room explicitly ('that sounds really frustrating/scary') before anything else.", "Provide accurate, balanced information only once the emotional temperature has come down.", "Offer support resources appropriate to the situation (counselling, social work, patient organizations, MAiD-adjacent conversations require particular sensitivity and scope-of-practice awareness).", "Close with a concrete next step and an open door for further questions."], "pitfalls": ["Rushing to 'fix' the conversation with facts before validating emotion", "Overstepping scope of practice on sensitive topics (e.g., MAiD) instead of validating and appropriately referring", "Sounding rehearsed/scripted rather than present with the patient"]}];

window.OSCE_STATIONS = [{"id": "o1", "ti": "New Prescription: Metformin", "tl": 5, "type": "newrx", "sc": "Mr. David Chen, 55, is picking up his first prescription for metformin 500 mg PO BID, newly diagnosed with type 2 diabetes. He tells the technician he's worried about “the sugar pill making him gain weight.”", "ta": "Counsel Mr. Chen on his new metformin prescription.", "cl": ["Introduces self and confirms patient identity (name + DOB)", "Asks what the physician told him about the medication and diagnosis", "Screens for allergies, other medications (incl. OTC/herbals), and renal/liver history", "Explains action in plain language (helps the body use its own insulin; does not typically cause weight gain)", "Explains instructions — take with food to reduce GI upset; may be titrated over time", "Covers expected side effects (transient GI upset) and rare serious risk (lactic acidosis) without alarming him", "Advises holding metformin around IV contrast dye studies or surgery", "Gives red flags (severe vomiting, unusual muscle pain, difficulty breathing) and monitoring plan (A1C q3 months)", "Checks understanding, invites questions, closes with follow-up"], "mn": "Framework: SAILS — Store, Action, Instructions, Life effects, Seek help."}, {"id": "o2", "ti": "New Prescription: Warfarin", "tl": 5, "type": "newrx", "sc": "Mrs. Eleanor Vasquez, 70, is starting warfarin 5 mg daily for newly diagnosed atrial fibrillation. She takes ibuprofen occasionally for arthritis and eats a diet rich in leafy greens.", "ta": "Counsel Mrs. Vasquez on her new warfarin therapy.", "cl": ["Introduction, identity confirmation, privacy check", "Asks about diet, other medications (flags OTC ibuprofen), alcohol use, allergies", "Explains action in plain language (prevents clot formation)", "Explains INR monitoring purpose, frequency, and target range", "Counsels on CONSISTENT (not avoided) vitamin K intake", "Advises against regular NSAID use; recommends acetaminophen and discussion with prescriber", "Reviews bleeding signs to watch for (bruising, blood in urine/stool, severe headache)", "Advises informing all prescribers/dentists about warfarin use before any new drug or procedure", "Closes, checks understanding, offers follow-up"], "mn": "Memory anchor: “CHAMPS” raise INR — Cipro, azoles, Metronidazole, Phenytoin, Sulfonamides."}, {"id": "o3", "ti": "OTC Triage: Chronic Cough", "tl": 5, "type": "otc", "sc": "A 61-year-old man asks for a “strong cough syrup.” The cough is dry, not productive, and has lasted about 6 weeks. He takes ramipril for hypertension.", "ta": "Assess and counsel this patient using an appropriate framework.", "cl": ["Introduces self, clarifies who the medication is for", "WWWHAM-style assessment: onset/duration, character, associated symptoms, what's been tried, medications/history", "Identifies ramipril as the likely cause of the chronic dry cough", "Recognizes red flag: cough >3–4 weeks warrants medical assessment", "Avoids simply recommending a cough suppressant without addressing the cause", "Recommends follow-up with prescriber to discuss switching to an ARB", "Explains the rationale in plain language — common, not dangerous, but worth addressing", "Checks understanding and offers appropriate referral"], "mn": "Exam trap: ACE-inhibitor cough is a classic OSCE setup — always ask about medications."}, {"id": "o4", "ti": "Adverse Drug Reaction: Statin Myopathy", "tl": 5, "type": "adr", "sc": "Mrs. Okafor, 66, calls the pharmacy reporting new muscle aches in both thighs and dark-coloured urine since starting atorvastatin 40 mg three weeks ago.", "ta": "Respond to this call appropriately.", "cl": ["Introduces self, confirms patient identity", "Gathers details: onset, severity, bilaterality, dark urine, fever/weakness", "Recognizes possible statin-induced myopathy/rhabdomyolysis (dark urine is a serious red flag)", "Advises stopping the statin immediately and seeking prompt (same-day) medical assessment", "Explains the need for urgent CK and renal function testing", "Does not minimize symptoms or suggest 'wait and see'", "Documents the call and communicates with the prescriber", "Reassures the patient and outlines next steps and alternative options once safe", "Provides safety-netting: when to go to the ER"], "mn": "Symptom pattern: muscle pain + dark urine = STOP statin + check CK now."}, {"id": "o5", "ti": "Non-Adherence: Antihypertensive", "tl": 5, "type": "adherence", "sc": "Mr. Singh, 58, admits he stopped taking his amlodipine two months ago because “I don't want to be on pills for the rest of my life,” and he feels fine.", "ta": "Have this conversation with Mr. Singh using a patient-centred approach.", "cl": ["Builds rapport with a non-judgmental tone", "Explores his reasons and beliefs without confrontation", "Acknowledges his feelings rather than lecturing", "Explains the asymptomatic nature of hypertension and long-term risks in plain language", "Uses motivational interviewing — explores what matters to him personally", "Explores practical barriers (cost, side effects, forgetfulness) alongside beliefs", "Offers to problem-solve together (alternative agent, dosing aid, follow-up BP check)", "Avoids ultimatums; respects autonomy while being clear about risk", "Closes with one concrete, actionable next step"], "mn": "Framework: explore → acknowledge → inform → collaborate → follow up."}, {"id": "o6", "ti": "Prescriber Call: Renal Dosing (SBAR)", "tl": 5, "type": "prescribercall", "sc": "A new prescription arrives for metformin 1000 mg BID for Mrs. Ahmed, 74, whose chart shows an eGFR of 25 mL/min/1.73m² from last week's labs.", "ta": "Call the prescriber's office to discuss this prescription using a structured framework.", "cl": ["Introduces self and pharmacy clearly", "Situation: states reason for the call up front", "Background: patient age, relevant history, recent labs", "Assessment: metformin inappropriate at this eGFR — lactic acidosis risk", "Recommendation: hold metformin, consider alternative, or confirm awareness of recent labs", "States the concern clearly and concisely, not vaguely", "Is respectful and collaborative, not confrontational", "Proposes a concrete next step or alternative agent", "Confirms the plan and who will follow up with the patient, then documents the call"], "mn": "Framework: SBAR — Situation, Background, Assessment, Recommendation."}, {"id": "o7", "ti": "New Prescription: Inhaler Technique", "tl": 5, "type": "newrx", "sc": "Ms. Petrov, 24, is newly diagnosed with asthma and picking up her first salbutamol pMDI plus a low-dose ICS-formoterol inhaler.", "ta": "Counsel Ms. Petrov on both inhalers, including technique.", "cl": ["Introduction and identity confirmation", "Asks what she was told about her diagnosis and each medication's purpose", "Distinguishes reliever vs. maintenance/anti-inflammatory purpose clearly", "Demonstrates/explains pMDI technique: shake, exhale fully away from device, actuate at start of slow deep breath, hold ~10 seconds", "Mentions spacer use, especially for the ICS-containing inhaler", "Advises rinsing mouth after the ICS inhaler to prevent oral thrush", "Explains signs of poor control and when to seek urgent care", "Checks technique understanding by asking her to explain or demonstrate it back", "Closes with a follow-up plan (e.g., asthma action plan)"], "mn": "Technique cue: shake → exhale → actuate + slow inhale → hold 10 sec."}, {"id": "o8", "ti": "Narcotic Refusal: Lost Prescription", "tl": 5, "type": "refusal", "sc": "A regular patient calls saying he lost his oxycodone prescription, filled 3 days ago, and asks for an early refill “just this once.”", "ta": "Handle this call appropriately, balancing empathy with regulatory requirements.", "cl": ["Introduces self and listens with an empathetic, non-accusatory tone", "Clearly explains narcotic prescriptions cannot be refilled/replaced without a new prescription (CDSA), regardless of the reason", "Explains the regulatory reasoning in plain, respectful language rather than a blunt refusal", "Sensitively assesses for safety concerns (withdrawal, pain crisis) without being accusatory", "Offers to contact the prescriber's office on the patient's behalf", "Avoids judgment even where diversion is a possible concern", "Documents the interaction thoroughly", "Discusses safe storage of controlled substances going forward if relevant", "Closes with clear next steps for the patient"], "mn": "For NARCS: no verbal orders, no transfers, no refills — everything needs paper."}, {"id": "o9", "ti": "New Prescription: Levothyroxine", "tl": 5, "type": "newrx", "sc": "Mrs. Thompson, 45, is picking up her first prescription for levothyroxine 75 mcg daily for newly diagnosed hypothyroidism. She takes a daily calcium supplement.", "ta": "Counsel Mrs. Thompson on her new levothyroxine.", "cl": ["Introduction and identity confirmation", "Asks what she understands about her diagnosis and the medication", "Explains action in plain language (replaces a hormone her thyroid isn't making enough of)", "Critical instruction: empty stomach, 30–60 minutes before breakfast, same time daily", "Identifies the calcium supplement as interacting — separate by ≥4 hours", "Explains effects are gradual and dose may be adjusted based on follow-up labs", "Explains monitoring plan (TSH rechecked ~6–8 weeks after starting/dose change)", "Reviews signs of over-/under-replacement to report", "Checks understanding, invites questions, closes with follow-up"], "mn": "Separate levothyroxine from calcium/iron by ≥4 hours — chelation cuts absorption."}, {"id": "o10", "ti": "New Prescription: Apixaban with Renal Check", "tl": 5, "type": "newrx", "sc": "Mr. Ibrahim, 78, is starting apixaban 5 mg BID for newly diagnosed atrial fibrillation. Recent labs: SCr 110 µmol/L, weight 58 kg.", "ta": "Counsel Mr. Ibrahim on his new anticoagulant, including confirming dose appropriateness.", "cl": ["Introduction and identity confirmation", "Reviews apixaban dose-reduction criteria (age ≥80, weight ≤60 kg, SCr ≥133 µmol/L — reduce if ≥2 of 3 met) and correctly applies them to this patient", "Explains action in plain language (prevents stroke-causing clots, no routine blood test needed unlike warfarin)", "Explains twice-daily dosing and what to do for a missed dose", "Reviews bleeding precautions and signs to report", "Advises informing all healthcare providers, including dentists, before procedures", "Cautions against combining with NSAIDs or other bleeding-risk agents without medical advice", "Notes renal function should still be reassessed periodically", "Checks understanding, closes with a follow-up plan"], "mn": "Apixaban reduced dose needs ≥2 of: age ≥80, weight ≤60 kg, SCr ≥133 µmol/L."}, {"id": "n1", "ti": "New Prescription: Rivaroxaban", "tl": 5, "type": "newrx", "sc": "Mr. Antoine Fortin, 68, is picking up his first prescription for rivaroxaban 20 mg once daily for newly diagnosed nonvalvular atrial fibrillation. He mentions he usually skips breakfast and just has coffee in the morning.", "ta": "Counsel Mr. Fortin on his new anticoagulant.", "cl": ["Introduces self, confirms patient identity (name + DOB), and checks privacy/consent to counsel", "Asks what he was told about his diagnosis and why this medication was prescribed", "Screens for allergies, other medications (including NSAIDs/ASA), and renal function history", "Explains action in plain language (reduces the risk of a stroke-causing clot forming in the heart)", "Critical instruction: rivaroxaban 20 mg must be taken WITH FOOD — a full meal — since absorption drops substantially on an empty stomach", "Addresses his skipped-breakfast habit directly, advising he take it with his largest meal of the day at a consistent time", "Reviews bleeding precautions and signs to report (unusual bruising, blood in urine/stool, severe headache)", "Advises informing all prescribers and dentists about rivaroxaban before any new drug or procedure", "Checks understanding, invites questions, and closes with a follow-up plan (periodic renal function check)"], "mn": "Exam trap: rivaroxaban's absorption depends on food at the 15/20 mg doses — apixaban and dabigatran carry no such requirement."}, {"id": "n2", "ti": "New Prescription: Empagliflozin", "tl": 5, "type": "newrx", "sc": "Ms. Priya Nair, 59, is starting empagliflozin 10 mg once daily added to her metformin for type 2 diabetes with early kidney protection in mind. She mentions she's leaving for a two-week trip with long flights and is prone to yeast infections.", "ta": "Counsel Ms. Nair on her new SGLT2 inhibitor prescription.", "cl": ["Introduces self, confirms identity, and checks what she understands about why this was added to her regimen", "Screens allergies, current renal function (eGFR), and other medications, including diuretics", "Explains action in plain language (causes the kidneys to remove extra sugar through the urine)", "Warns of increased risk of genital yeast infections and reviews hygiene measures and prompt treatment if symptoms occur", "Explains the rare but serious risk of euglycemic diabetic ketoacidosis, which can occur even with normal blood glucose", "Reviews sick-day rules — hold the dose during illness, poor oral intake, dehydration, or before surgery", "Advises adequate hydration, especially relevant to her upcoming travel and long flights", "Reviews signs of dehydration/hypotension and DKA (nausea, vomiting, abdominal pain, unusual fatigue) to report immediately", "Checks understanding and closes with a follow-up/monitoring plan"], "mn": "SGLT2 inhibitors can trigger DKA with a NORMAL blood glucose — 'euglycemic DKA' is the classic exam trap, and sick-day rules are the counterpoint."}, {"id": "n3", "ti": "New Prescription: Levetiracetam", "tl": 5, "type": "newrx", "sc": "Jordan Wu, 22, is picking up a new prescription for levetiracetam 500 mg PO BID after a first unprovoked seizure. He works as a delivery driver and is worried about missing work.", "ta": "Counsel Jordan on his new antiepileptic medication.", "cl": ["Introduces self, confirms identity, and asks what the neurologist told him about the diagnosis and plan", "Screens for allergies, other medications, and alcohol use", "Explains action in plain language (calms overactive electrical activity in the brain to help prevent further seizures)", "Emphasizes strict adherence — missed doses can trigger breakthrough seizures", "Counsels on mood/behavioural side effects (irritability, low mood) as a known class effect, and to report rather than stop the drug on his own", "Discusses driving restrictions — a mandated seizure-free interval applies before he can legally resume driving, and to confirm the exact timeline with his prescriber", "Explains the drug must never be stopped abruptly, even if he feels well, due to the risk of rebound/withdrawal seizures", "Reviews common early side effects (drowsiness, dizziness) and when to call the pharmacy versus seek urgent care", "Checks understanding, invites questions, and closes with a follow-up plan"], "mn": "Antiepileptics are never stopped abruptly, even after a single seizure — always taper under medical supervision."}, {"id": "n4", "ti": "OTC Triage: Spreading Leg Redness", "tl": 5, "type": "otc", "sc": "A young man asks for 'the strongest bug bite cream' for a red patch on his lower leg he first noticed two days ago after gardening. On questioning, the area is now warm, tender, and visibly larger than yesterday, and he mentions feeling feverish and tired since last night.", "ta": "Assess and counsel this patient using an appropriate self-care framework.", "cl": ["Introduces self and clarifies the presenting complaint", "WWHAM-style assessment: onset, character, rate of spread, associated systemic symptoms (fever, fatigue), relevant medical history and allergies", "Identifies red flags: spreading erythema, warmth, tenderness, and systemic fever — inconsistent with a simple insect bite", "Recognizes this presentation is concerning for cellulitis and is not appropriate for self-care", "Avoids simply recommending a topical antihistamine or hydrocortisone without addressing the underlying concern", "Explains the concern in plain, non-alarming language and the need for prompt (same-day) medical assessment", "Advises interim comfort measures (elevation, tracking the border with a marker and date) while arranging assessment", "Provides safety-netting: seek emergency care immediately if red streaking develops, fever worsens, or the area rapidly enlarges", "Checks understanding and confirms he has a way to be seen promptly today"], "mn": "Spreading warmth plus fever on a 'bug bite' is a cellulitis red flag — refer same-day, don't just hand over a cream."}, {"id": "n5", "ti": "OTC Triage: Burning with Urination in Pregnancy", "tl": 5, "type": "otc", "sc": "A woman who appears to be pregnant asks for cranberry extract capsules and a urinary alkalinizing powder for burning with urination that started yesterday. When asked, she confirms she is 22 weeks pregnant.", "ta": "Assess and counsel this patient using an appropriate self-care framework.", "cl": ["Introduces self and assesses the symptoms: onset, frequency, urgency, flank pain, fever, visible blood in urine", "Confirms pregnancy status and gestational age directly", "Recognizes pregnancy as an automatic exclusion from self-treatment for urinary symptoms", "Screens specifically for red flags suggesting pyelonephritis (fever, flank pain, nausea/vomiting) requiring urgent rather than routine referral", "Explains the rationale in plain language — an untreated urinary infection in pregnancy carries risk to both her and the pregnancy", "Does not recommend cranberry extract or a urinary alkalinizer as sole treatment", "Refers promptly for urinalysis/culture and pregnancy-safe antibiotic therapy", "Communicates urgency clearly without unnecessarily alarming her", "Checks understanding and confirms she has access to prompt care today"], "mn": "Pregnancy is an automatic red flag for urinary symptoms — always refer for testing and treatment, never self-care alone."}, {"id": "n6", "ti": "Adverse Drug Reaction: Bloody Diarrhea on Clindamycin", "tl": 5, "type": "adr", "sc": "A patient calls the pharmacy reporting five days of profuse watery diarrhea with occasional streaks of blood, cramping, and a low-grade fever, six days into a course of clindamycin his dentist prescribed for a tooth infection.", "ta": "Respond to this call appropriately.", "cl": ["Introduces self and confirms patient identity", "Gathers details: onset relative to starting clindamycin, stool frequency and character, fever, abdominal pain", "Recognizes this presentation as concerning for Clostridioides difficile-associated diarrhea rather than routine antibiotic-associated GI upset", "Advises stopping the clindamycin now", "Advises against antimotility agents such as loperamide, which can worsen the condition", "Advises prompt (same-day) medical assessment with stool testing for C. difficile toxin", "Explains that confirmed cases require a different targeted antibiotic (e.g., oral vancomycin or fidaxomicin), not just supportive care alone", "Advises hand hygiene with soap and water rather than alcohol-based sanitizer alone, since alcohol does not kill C. difficile spores", "Documents the call, communicates the concern to the prescriber, and provides safety-netting for worsening symptoms or dehydration"], "mn": "Bloody diarrhea after antibiotics means suspect C. difficile — stop the drug, skip the loperamide, and wash with soap, not just gel."}, {"id": "n7", "ti": "Adverse Drug Reaction: Lip and Tongue Swelling on Lisinopril", "tl": 5, "type": "adr", "sc": "A patient's spouse calls in a panic, saying her husband, who started lisinopril for hypertension eleven days ago, suddenly has a swollen lip and tongue and is having trouble speaking clearly.", "ta": "Respond to this call appropriately.", "cl": ["Introduces self, stays calm, and gathers essential details quickly: onset, breathing difficulty, voice change, throat tightness", "Recognizes this as angioedema, a rare but life-threatening ACE-inhibitor reaction", "Immediately advises calling 911 or going to the emergency department now, without delaying for further questions given possible airway compromise", "Clearly states the lisinopril must be stopped and never taken again", "Explains this reaction can occur days to weeks into therapy, not only with the first dose", "Advises against future use of any ACE inhibitor, and flags the need for caution (lower but nonzero cross-reactivity) if an ARB is considered later", "Ensures the reaction is documented as an allergy/intolerance in the patient's profile once the emergency is addressed", "Follows up with the family afterward to discuss an alternative antihypertensive class with the prescriber", "Does not minimize the situation or suggest waiting to see if it improves on its own"], "mn": "ACE-inhibitor angioedema can strike weeks into therapy — swelling of the lips, tongue, or throat is a 911 emergency, not a call-tomorrow issue."}, {"id": "n8", "ti": "Immunization: Influenza Vaccine and Egg Allergy", "tl": 5, "type": "immunization", "sc": "Mr. Yusuf, 74, is due for his annual influenza vaccine but hesitates, telling you he was informed years ago that he 'can't get the flu shot' because he once had hives after eating scrambled eggs.", "ta": "Screen and counsel Mr. Yusuf on his influenza immunization.", "cl": ["Confirms identity, indication, and date of his last influenza vaccine", "Takes a focused history of the egg reaction to characterize its severity (hives only, no anaphylaxis, airway involvement, or hospitalization)", "Correctly identifies that egg allergy, even if severe, is NOT a contraindication to current influenza vaccines and no special precautions beyond routine observation are needed", "Screens for true contraindications/precautions: anaphylaxis to a prior dose of influenza vaccine itself or a vaccine component, current moderate-to-severe acute illness", "Obtains informed consent, explaining common local/systemic reactions and rare serious reactions in balanced, non-alarming language", "Describes proper administration technique and site", "Reviews aftercare: the standard 15-minute observation period and how to manage soreness or low-grade fever", "Corrects the outdated belief respectfully, without making him feel foolish for having asked", "Documents the immunization per the provincial immunization program"], "mn": "Egg allergy, even anaphylactic, is no longer a contraindication to flu vaccination — a persistent myth worth actively un-learning."}, {"id": "n9", "ti": "Immunization: Pediatric Catch-Up During Chemotherapy", "tl": 5, "type": "immunization", "sc": "A mother brings in her 6-year-old daughter for catch-up immunizations, including a second MMR dose, ahead of starting school. She mentions her daughter was recently diagnosed with acute lymphoblastic leukemia and started chemotherapy last month.", "ta": "Screen and counsel the mother on the requested immunizations.", "cl": ["Confirms identity, immunization history, and which vaccines are due for catch-up", "Identifies active chemotherapy-induced immunosuppression as a contraindication to live vaccines, including MMR, at this time", "Explains the reasoning in plain language — a live vaccine could cause actual infection in a child whose immune system cannot mount a normal response right now", "Clarifies that inactivated vaccines (e.g., inactivated influenza) generally remain appropriate and should not be delayed", "Advises deferring the MMR dose until cleared by the oncology team, with a plan to complete the series once immune function recovers", "Recommends household contacts stay up to date on their own vaccinations to indirectly protect the child", "Refers back to the treating oncologist or an immunization specialist for a personalized catch-up schedule rather than guessing", "Documents the deferred vaccine and the specific reason clearly in her record", "Closes with empathy, acknowledging this is a stressful and overwhelming time for the family"], "mn": "Live vaccines (MMR, varicella, live intranasal flu) are held during immunosuppression — inactivated vaccines generally are not."}, {"id": "n10", "ti": "Calculation Station: Pediatric Amoxicillin Suspension", "tl": 5, "type": "calculation", "sc": "A prescription arrives for amoxicillin oral suspension for a 3-year-old boy weighing 18 kg with acute otitis media, dosed at 40 mg/kg/day divided into three doses daily. The pharmacy stocks amoxicillin suspension 250 mg/5 mL.", "ta": "Calculate the volume of suspension required per dose and explain your reasoning to the examiner.", "cl": ["Extracts the relevant numbers: weight 18 kg, dose 40 mg/kg/day, three divided doses daily, stock concentration 250 mg/5 mL", "Sets up the total daily dose calculation explicitly: 40 mg/kg/day x 18 kg = 720 mg/day", "Divides correctly by the number of daily doses: 720 mg / 3 = 240 mg per dose", "Converts the per-dose amount to volume using the stock concentration (250 mg/5 mL = 50 mg/mL): 240 mg / 50 mg/mL = 4.8 mL per dose", "States the correct final answer clearly: 4.8 mL per dose, given three times daily", "Sanity-checks the answer against a typical single-dose suspension volume for a child this size (plausible, not an implausible extreme)", "Explains the reasoning aloud in an organized, stepwise manner rather than presenting only a final number", "Confirms the total daily volume (14.4 mL/day) is reasonable relative to the bottle size to be dispensed", "Notes the importance of counselling on use of an oral dosing syringe rather than a household spoon"], "mn": "Always convert dose to mg per administration, then mg to volume using the STOCK concentration, in that order — skipping a step is where marks are lost."}, {"id": "n11", "ti": "Calculation Station: Weight-Based Heparin Infusion", "tl": 5, "type": "calculation", "sc": "An 80 kg patient is to be started on an intravenous heparin infusion at an ordered rate of 18 units/kg/hour, using a premixed bag containing 25,000 units of heparin in 250 mL of D5W.", "ta": "Calculate the infusion pump rate in mL/hour and explain your reasoning to the examiner.", "cl": ["Extracts the relevant numbers: weight 80 kg, ordered rate 18 units/kg/hr, bag concentration 25,000 units/250 mL", "Calculates the required hourly dose first: 18 units/kg/hr x 80 kg = 1,440 units/hour", "Determines the bag concentration explicitly: 25,000 units / 250 mL = 100 units/mL", "Converts the hourly dose to a pump rate: 1,440 units/hour / 100 units/mL = 14.4 mL/hour", "States the correct final answer clearly with units: 14.4 mL/hour", "Sanity-checks that the rate is physiologically reasonable for a weight-based heparin infusion, not an extreme outlier", "Shows all intermediate steps and units explicitly rather than jumping straight to a final number", "Notes that heparin infusions require regular aPTT or anti-Xa monitoring with dose adjustment per nomogram", "Explains the calculation logic aloud clearly and confidently to the examiner"], "mn": "For weight-based infusions, find units-per-hour needed FIRST, then convert to mL/hour using the bag's concentration — never the reverse order."}, {"id": "n12", "ti": "Patient Assessment: New Low Back Pain", "tl": 5, "type": "assessment", "sc": "Mr. Delgado, 44, a warehouse worker, comes in asking for something stronger than ibuprofen for low back pain that started two days ago after lifting a heavy box. He denies any leg symptoms when asked in general terms.", "ta": "Take a focused history and determine an appropriate plan for Mr. Delgado.", "cl": ["Introduces self and explains the purpose of the questions", "Applies a structured history: onset (lifting injury), provocation/palliation, quality, region/radiation, severity, timing and duration", "Actively and specifically screens for red flags: leg weakness or numbness, saddle anesthesia, new bowel or bladder changes, fever, unexplained weight loss, prior cancer history, significant trauma, IV drug use", "Asks about current medications, including the ibuprofen already tried (dose, duration, effectiveness), and allergies", "Confirms no neurological red flags are present, supporting a working diagnosis of mechanical/musculoskeletal low back strain", "States a clear plan: appropriate analgesic options, staying active rather than strict bed rest, heat application, and an expected recovery timeline", "Explains specifically when to return or seek urgent care if red flag symptoms develop", "Explains the plan to the patient in plain, reassuring language", "Documents the assessment and follow-up plan"], "mn": "Cauda equina red flags — saddle numbness, bowel/bladder changes, bilateral leg weakness — must always be asked about directly, even if the patient doesn't volunteer them."}, {"id": "n13", "ti": "Difficult Conversation: New Palliative Pain Prescription", "tl": 5, "type": "difficult", "sc": "Mrs. Alaoui, 61, was recently diagnosed with metastatic pancreatic cancer and comes in tearful with a new prescription for a long-acting opioid for pain control, saying, 'I don't understand why we're jumping straight to this — does this mean it's really over?'", "ta": "Have this conversation with Mrs. Alaoui.", "cl": ["Invites her to sit and finishes listening to what she's feeling before responding with information", "Does not interrupt or rush to correct her assumption", "Validates her emotion explicitly, acknowledging this is frightening and overwhelming news, before providing any facts", "Gently clarifies, once she seems ready to hear it, that starting a stronger pain medication is about controlling symptoms and quality of life, not necessarily an immediate end-of-life signal", "Provides balanced, accurate information about the medication itself (purpose, how it works, common side effects such as constipation and initial drowsiness, and that doses are titrated to comfort)", "Avoids overstepping scope of practice by making prognostic statements that belong to her oncology team", "Offers appropriate support resources (palliative care team, counselling or social work, patient support organizations)", "Checks in on how she's feeling and whether she has support at home", "Closes with a concrete next step (follow-up call, contact information) and leaves the door open for further questions"], "mn": "Validate the emotion first — a frightened patient cannot absorb medication counselling until she feels heard."}, {"id": "m1", "ti": "New Prescription: Methotrexate for RA", "tl": 5, "type": "newrx", "sc": "Mrs. Patricia Nguyen, 52, is starting methotrexate 15 mg PO once weekly for newly diagnosed moderate rheumatoid arthritis, along with folic acid supplementation. She mentions she occasionally takes trimethoprim-sulfamethoxazole for recurrent urinary tract infections.", "ta": "Counsel Mrs. Nguyen on her new methotrexate therapy.", "cl": ["Introduces self, confirms patient identity, and checks privacy to counsel", "Asks what she understands about her diagnosis and why methotrexate was chosen", "States clearly that the dose is taken ONCE WEEKLY on a fixed day, never daily", "Explains folic acid is taken on a different day to reduce GI upset and blood count side effects", "Identifies trimethoprim-sulfamethoxazole as a significant interaction (increased bone marrow suppression risk) and advises contacting the prescriber before continuing it", "Explains onset is slow (weeks to months) and short-term NSAID use may still be needed for symptom control", "Reviews red flags to report immediately: unusual bruising/bleeding, mouth sores, persistent cough or shortness of breath, yellowing of skin", "Confirms reliable contraception given teratogenicity and advises against alcohol use", "Explains the monitoring plan (baseline and periodic CBC, liver enzymes, renal function) and closes with follow-up"], "mn": "\"Once weekly, not daily\" is the single highest-stakes counselling point for methotrexate — accidental daily dosing has caused fatalities."}, {"id": "m2", "ti": "New Prescription: Alendronate for Osteoporosis", "tl": 5, "type": "newrx", "sc": "Mrs. Loretta Fields, 68, is picking up her first prescription for alendronate 70 mg PO once weekly after a bone density scan showed a T-score of -2.6 at the hip. She also takes a combined calcium and vitamin D supplement each morning.", "ta": "Counsel Mrs. Fields on her new alendronate prescription, including proper administration.", "cl": ["Introduces self, confirms identity, and asks what she was told about her diagnosis", "Explains the action in plain language (slows bone breakdown to reduce fracture risk)", "States the critical administration rule: take first thing in the morning, on an empty stomach, with a full glass of plain water only", "Instructs her to remain upright (sitting or standing) for at least 30 minutes and not eat, drink, or take other medications during that time", "Identifies the calcium/vitamin D supplement as needing to be separated from the dose by at least 30-60 minutes to avoid impaired absorption", "Reviews red flags to report: new or worsening heartburn/chest pain, jaw pain, or unusual thigh/groin pain, and advises informing her dentist before invasive dental work", "Discusses that initial therapy typically runs 3-6 years before reassessing a possible drug holiday", "Checks her understanding and closes with a follow-up plan (repeat bone density testing in about 3 years)"], "mn": "Empty stomach, full glass of plain water, and staying upright for 30 minutes are three separate rules — missing any one risks esophageal irritation or ulceration."}, {"id": "m3", "ti": "Non-Adherence: Antipsychotic", "tl": 5, "type": "adherence", "sc": "Mr. Adrian Kowalski, 27, has been stable on olanzapine 10 mg daily for schizophrenia for the past year. He quietly admits he has cut his dose in half over the last month because he has gained 8 kg and is embarrassed about it.", "ta": "Have this conversation with Mr. Kowalski using a patient-centred approach.", "cl": ["Builds rapport and opens with a non-judgmental question about how the medication has been going", "Explores his feelings about the weight gain without lecturing or dismissing his concern", "Acknowledges the impact of weight gain as valid before providing any clinical information", "Explains the risk of a reduced dose: possible relapse of psychotic symptoms and loss of hard-won stability", "Screens for early relapse warning signs (sleep changes, increasing suspiciousness, disorganized thinking)", "Discusses realistic options collaboratively (lifestyle support, or discussing a switch to an agent with lower weight-gain liability with his prescriber) rather than him unilaterally adjusting the dose", "Avoids ultimatums and respects his autonomy while being clear about relapse risk", "Closes with one concrete next step, such as arranging a prescriber follow-up before any further dose changes"], "mn": "Weight gain is one of the leading drivers of covert antipsychotic non-adherence — ask about it directly rather than waiting for it to surface as relapse."}, {"id": "m4", "ti": "Non-Adherence: Antidepressant", "tl": 5, "type": "adherence", "sc": "Ms. Farah Haidari, 33, was started on sertraline 50 mg daily six weeks ago for major depressive disorder. She stopped taking it about a week ago because she \"felt back to normal\" and disliked some of the side effects.", "ta": "Have this conversation with Ms. Haidari using a patient-centred approach.", "cl": ["Builds rapport and asks an open-ended question about how she has been feeling since stopping", "Explores both her reasons (feeling better and side effects) without judgment", "Screens for antidepressant discontinuation symptoms since stopping abruptly (flu-like symptoms, insomnia, nausea, dizziness, sensory changes)", "Acknowledges her improvement as encouraging but explains that early symptom relief does not mean the depression has fully resolved", "Explains the recommended minimum duration of therapy (continuing at least 6-12 months after symptoms improve) to prevent relapse", "Asks which specific side effects bothered her and discusses management options or a possible adjustment instead of stopping outright", "Briefly screens for safety (mood, suicidal ideation) given the recent unplanned discontinuation", "Collaborates on a concrete next step, such as restarting under guidance with a proper tapering plan for the future"], "mn": "Feeling better at 6 weeks is the expected pharmacologic response, not permission to stop — full course is a minimum of 6-12 months after remission."}, {"id": "m5", "ti": "Prescriber Call: Lithium-ACE Inhibitor Interaction", "tl": 5, "type": "prescribercall", "sc": "Mr. Owen Bracken, 61, has been stable on lithium 900 mg daily for bipolar disorder, with a recent level of 0.7 mmol/L. His family physician's office faxes a new prescription for ramipril 5 mg daily for newly diagnosed hypertension.", "ta": "Call the prescriber's office to discuss this new prescription using a structured framework.", "cl": ["Introduces self and pharmacy clearly, and states the reason for the call up front", "Situation: a new ACE inhibitor is being added for a patient stable on lithium", "Background: current lithium dose, most recent level, duration of stability, no other recent medication changes", "Assessment: explains specifically that ACE inhibitors reduce renal lithium clearance and can precipitate lithium toxicity, rather than a vague concern", "Recommendation: proposes an alternative antihypertensive (e.g., a dihydropyridine calcium channel blocker) or, if the ACE inhibitor is preferred, closer lithium level and renal function monitoring after initiation", "Confirms who will follow up with the patient and by when", "Is collaborative and respectful, not confrontational", "Documents the call and its outcome"], "mn": "NSAIDs and ACE inhibitors/ARBs both raise lithium levels by reducing renal clearance — caffeine, by contrast, lowers them."}, {"id": "m6", "ti": "Prescriber Call: Gabapentin Accumulation in Declining Renal Function", "tl": 5, "type": "prescribercall", "sc": "Mrs. Beulah Ortiz, 74, has been taking gabapentin 600 mg three times daily for diabetic peripheral neuropathy. Her latest labs show her eGFR has fallen from 55 to 24 mL/min/1.73m². Her daughter calls the pharmacy reporting her mother has become unusually drowsy and unsteady on her feet this week.", "ta": "Call the prescriber's office to discuss this concern using a structured framework.", "cl": ["Introduces self and pharmacy clearly, and states the reason for the call up front", "Situation: new sedation and unsteadiness in a patient on an unchanged gabapentin dose", "Background: notes gabapentin is renally eliminated with no hepatic metabolism, and reports the recent drop in eGFR alongside the current dosing frequency", "Assessment: states the specific concern — gabapentin accumulation from declining renal function likely causing sedation and ataxia, with fall risk", "Recommendation: proposes a renally adjusted dose or frequency reduction and asks whether repeat renal function testing is planned", "Confirms the plan for reassessing the patient and who communicates it to the family", "Is collaborative and respectful, not confrontational", "Documents the call and communicates the outcome to the daughter"], "mn": "Gabapentin is roughly 90% renally eliminated unchanged — a falling eGFR with new sedation or ataxia in an older adult should immediately raise suspicion of drug accumulation."}, {"id": "m7", "ti": "Refusal: Altered Controlled-Drug Prescription", "tl": 5, "type": "refusal", "sc": "A man presents a written prescription for clonazepam 0.5 mg where the quantity appears to have been changed from \"30\" to \"90\" in different ink, and the initials beside the change do not match the rest of the script.", "ta": "Handle this situation appropriately, balancing empathy with your professional and regulatory obligations.", "cl": ["Greets the patient calmly and privately, without immediately accusing him of wrongdoing", "Clearly explains that the pharmacy cannot fill a prescription with an alteration that cannot be verified as authorized by the prescriber", "Explains the reasoning in plain, non-accusatory language rather than a blunt refusal", "Contacts the prescriber's office directly to verify the intended quantity before proceeding with any fill", "Sensitively screens for safety concerns (withdrawal risk, diversion) without being accusatory", "Retains and documents the original prescription per policy rather than returning it if forgery is suspected", "Offers a concrete alternative, such as waiting while the office is contacted or dispensing the verified original quantity", "Documents the interaction thoroughly, including the discrepancy and the steps taken", "Reports to the regulatory authority if forgery is confirmed"], "mn": "An alteration in different ink or an unverifiable initial beside a controlled-drug quantity is a verify-before-you-fill trigger, not grounds for an on-the-spot accusation."}, {"id": "m8", "ti": "Medication Error: Wrong Strength Dispensed", "tl": 5, "type": "error", "sc": "Mrs. Anh Pham, 45, returns to the pharmacy after two days on what was supposed to be sertraline 50 mg daily, reporting she feels unusually jittery and nauseated. On review, the pharmacy dispensed sertraline 100 mg tablets in error.", "ta": "Manage this medication error appropriately with Mrs. Pham.", "cl": ["Acknowledges the error directly and honestly as soon as it is identified, without minimizing or deflecting", "Apologizes sincerely without excessive self-blame or alarming her unnecessarily", "Assesses her current symptoms and rules out signs of serious toxicity before reassuring her", "Gives clear clinical guidance on what to do now regarding today's and future doses", "Contacts the prescriber to inform them of the error and confirm the intended ongoing dose", "Corrects the prescription and provides the correct-strength medication at no charge", "Documents the error per the pharmacy's incident-reporting process", "Briefly explains what will change to reduce recurrence (e.g., an independent double-check at final verification) without being defensive", "Checks her understanding and offers follow-up contact if symptoms worsen"], "mn": "Dispensing errors must be disclosed fully and promptly — minimizing or deflecting blame is itself a professionalism failure, separate from the clinical error."}, {"id": "m9", "ti": "Medication Error: Wrong-Patient Bag Mix-Up", "tl": 5, "type": "error", "sc": "Two patients with similar names, Robert Sinclair and Robert St. Clair, were given each other's prescription bags at pickup. Mr. Sinclair calls the next day saying the bottle contains tablets he doesn't recognize, labeled with a name similar to his own.", "ta": "Manage this medication error appropriately with Mr. Sinclair.", "cl": ["Acknowledges the error directly and honestly, and apologizes sincerely", "Confirms exactly what medication and how many doses he actually took from the incorrect bag", "Assesses potential harm based on the specific drug taken, checking for interactions or contraindications with his own conditions, and gives clear instructions on what to do now", "Advises him not to take any further doses from the incorrect bag and to return it to the pharmacy", "Simultaneously initiates contact with the other patient to recover his correct bag and check whether he took any doses in error", "Notifies the prescriber(s) involved if clinically relevant", "Documents the incident per the pharmacy's incident-reporting process", "Identifies the system contributor (similar patient names) and states a concrete prevention step, such as independent identity/date-of-birth verification at pickup", "Closes with safety-netting: symptoms to watch for and when to seek urgent care"], "mn": "A similar-name mix-up needs a two-sided fix — both patients' bags and doses-taken must be traced, not just the one who happened to call first."}, {"id": "m10", "ti": "Assessment: Uncomplicated UTI Self-Referral", "tl": 5, "type": "assessment", "sc": "Ms. Danielle Okoro, 29, presents asking to be assessed for a urinary tract infection. She reports burning with urination and increased frequency for the past day, with no fever, flank pain, or vaginal discharge, and no prior UTI history. She confirms she is not pregnant.", "ta": "Assess Ms. Okoro using an appropriate framework and determine next steps.", "cl": ["Introduces self, confirms identity, and ensures privacy for a sensitive assessment", "Takes a focused history: onset, character, frequency/urgency, presence of blood in urine, vaginal symptoms", "Screens for upper tract or systemic red flags: fever, chills, flank or back pain, nausea/vomiting", "Screens for exclusions to self-referral assessment: pregnancy, male sex, immunocompromise, indwelling catheter, recurrent or relapsing infection, known renal abnormality", "Reviews allergy history and current medications before considering empiric antibiotic therapy", "States a working assessment of uncomplicated lower UTI and an appropriate first-line treatment option with rationale", "Explains the expected course, hydration advice, and timeframe for improvement", "Provides clear safety-netting: red flags requiring escalation, such as fever, flank pain, or symptoms not improving within 48 hours", "Checks her understanding and confirms a follow-up plan"], "mn": "Fever, flank pain, or male sex turns \"uncomplicated cystitis\" into a red flag needing referral rather than self-referral treatment."}, {"id": "m11", "ti": "Assessment: Dyspepsia with Red Flags", "tl": 5, "type": "assessment", "sc": "Mr. Harold Whitfield, 57, asks for something for \"heartburn and an upset stomach\" that has been going on for about six weeks. On further questioning, he also mentions unintentional weight loss and increasing difficulty swallowing solid food.", "ta": "Assess Mr. Whitfield using an appropriate framework and determine next steps.", "cl": ["Introduces self and takes a focused history of onset, character, timing, and aggravating/relieving factors", "Actively elicits and identifies red flags: new onset over age 50 with unexplained weight loss and difficulty swallowing", "Screens for additional red flags: blood in stool or vomit, black tarry stools, persistent vomiting, severe abdominal pain", "Reviews his medication history for contributing agents (e.g., NSAIDs, ASA, bisphosphonates) and relevant social history (smoking, alcohol)", "Recognizes that this combination of red flags makes self-care or OTC treatment inappropriate", "Clearly explains to the patient, without causing undue alarm, why referral is needed to rule out serious underlying causes", "Refers promptly to his physician for urgent assessment rather than recommending an antacid or a PPI trial", "Checks his understanding and offers to communicate with his physician's office if helpful"], "mn": "Weight loss plus difficulty swallowing in a patient over 50 with new dyspepsia is an automatic referral, not a PPI trial."}, {"id": "m12", "ti": "Difficult Conversation: Bereavement and Sedative Overuse", "tl": 5, "type": "difficult", "sc": "Mrs. Carol Jennings, 70, lost her husband of 45 years three months ago. She has been requesting early refills of her lorazepam 1 mg, prescribed PRN for anxiety, and admits she has been taking it most nights \"just to get some peace.\"", "ta": "Have this conversation with Mrs. Jennings.", "cl": ["Lets her speak fully about her loss before responding, without immediately jumping to the medication issue", "Validates her grief and the difficulty of the past three months explicitly, before discussing anything clinical", "Gently raises the pattern of increased lorazepam use once rapport is established, without shaming her", "Explores what the medication is helping with (sleep, anxiety, loneliness) to understand the underlying need", "Provides balanced information on the risks of regular benzodiazepine use in older adults (falls, dependence, cognitive effects) only once she feels heard", "Offers appropriate support resources, such as grief counselling or a bereavement support group, and suggests follow-up with her prescriber, rather than simply refusing the refill", "Collaborates on one concrete next step, such as a follow-up appointment to reassess her anxiety and sleep", "Closes with an open door for further conversation and avoids making her feel judged"], "mn": "Grief with escalating PRN benzodiazepine use is a difficult-conversation station, not a refusal station — validate the emotion first, address safety second."}, {"id": "m13", "ti": "Difficult Conversation: Family Conflict Over Palliative Pain Control", "tl": 5, "type": "difficult", "sc": "Mr. Desmond Okafor, 81, is in the palliative phase of advanced cancer and has clearly told the care team he wants his opioid dose kept as-is because it controls his pain well. His son calls the pharmacy insisting the dose be reduced because he is worried his father is \"too sedated and not himself.\"", "ta": "Have this conversation with the son.", "cl": ["Lets the son express his concerns fully before responding", "Validates his fear and distress about seeing his father sedated, without dismissing it", "Clarifies that the patient has expressed his own wishes and has the capacity to make this decision, respecting patient autonomy as the primary consideration", "Explains, in balanced and non-alarming language, that some sedation can be an expected trade-off in palliative pain control that the patient himself has accepted", "Does not unilaterally change the dose based on the son's request alone, and explains that any change requires discussion with the patient and the care team", "Offers to facilitate a joint conversation between the son, the patient, and the care team to address the concern", "Screens for any new safety concerns the son describes that could suggest true overdose rather than expected sedation, and escalates appropriately if so", "Closes with a concrete next step and offers ongoing support or resources for the family"], "mn": "When a competent patient's wishes and a family member's wishes conflict, the patient's autonomy governs — the pharmacist's role is to facilitate communication, not to silently comply with either side."}];
